 "content": "def transform(grid):
    H, W = len(grid), len(grid[0])
    seen, components = set(), []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack, comp = [(r, c)], []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < H and 0 <= nx < W and grid[ny][nx] and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            components.append(comp)
    comp = max(components, key=len)
    r0, r1 = min(r for r,c in comp), max(r for r,c in comp)
    c0, c1 = min(c for r,c in comp), max(c for r,c in comp)
    a = [row[c0:c1+1] for row in grid[r0:r1+1]]
    h, w = len(a), len(a[0])
    # Match the relative orientation of same-colored markers outside and
    # inside the panel by trying all eight square/rectangular symmetries.
    outside = [(r,c,grid[r][c]) for r in range(H) for c in range(W)
               if grid[r][c] and not (r0 <= r <= r1 and c0 <= c <= c1)]
    internal = {}
    external = {}
    for color in set(v for _,_,v in outside):
        ip = [(r-r0,c-c0) for r in range(r0,r1+1) for c in range(c0,c1+1) if grid[r][c] == color]
        ep = [(r,c) for r,c,v in outside if v == color]
        if len(ip) == len(ep) == 1:
            internal[color] = ip[0]
            external[color] = ep[0]
    colors = sorted(internal)
    transforms = [
        lambda r,c:(r,c),
        lambda r,c:(h-1-r,c),
        lambda r,c:(r,w-1-c),
        lambda r,c:(h-1-r,w-1-c),
        lambda r,c:(c,r),
        lambda r,c:(w-1-c,h-1-r),
        lambda r,c:(c,h-1-r),
        lambda r,c:(w-1-c,r),
    ]
    def relation(points):
        return tuple(((points[x][0] > points[y][0]) - (points[x][0] < points[y][0]),
                      (points[x][1] > points[y][1]) - (points[x][1] < points[y][1]))
                     for i,x in enumerate(colors) for y in colors[i+1:])
    target = relation(external)
    chosen = transforms[0]
    for f in transforms:
        if relation({color:f(*internal[color]) for color in colors}) == target:
            chosen = f
            break
    coords = [chosen(r,c) for r in range(h) for c in range(w)]
    oh, ow = max(r for r,c in coords)+1, max(c for r,c in coords)+1
    out = [[0]*ow for _ in range(oh)]
    for r in range(h):
        for c in range(w):
            y,x = chosen(r,c)
            out[y][x] = a[r][c]
    return out
